        const pt = s.professional_tax || 0;
        const tds = s.tds || 0;
        const loan = s.loan_deduction || 0;
        const advance = s.salary_advance || 0;
        const other = s.other_deduction || 0;
        const lop = s.lop_deduction || 0;
